"""Seleção editorial complementar. Não gera fatos nem infere causalidade."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
sources=[];events=[]
def source(id,title,url,kind='institutional',note=None):
    sources.append(dict(id=id,title=title,url=url,kind=kind,checkedAt='2026-10-27',**({'note':note} if note else {})))
def event(id,year,label,topics,actors,summary,context,decision,effects,limits,refs,interpretation=None,evidence='documented',date=None,related=None):
    events.append(dict(id=id,year=year,label=label,period='democracia',topics=topics,actors=actors,summary=summary,context=context,decision=decision,effects=effects,limits=limits,sources=refs,evidence=evidence,area='Brasil',related=related or [],**({'date':date} if date else {}),**({'interpretation':interpretation} if interpretation else {})))
